insert into public.events (id, title, kind, chapter, starts_at, minutes, venue, capacity, host_id, blurb) values
  ('00000000-0000-4000-9000-000000000001', 'General meeting', 'meetup', null, (current_date + ((2 - extract(dow from current_date)::int + 7) % 7) + -7)::timestamptz + interval '18 hours 30 minutes', 90, 'Main hall, North Street library', 80, '00000000-0000-4000-8000-000000702598', 'The season in numbers, the budget, and a vote on the next quests.'),
  ('00000000-0000-4000-9000-000000000002', 'Lightning talks', 'talk', 'East chapter', (current_date + ((3 - extract(dow from current_date)::int + 7) % 7) + -7)::timestamptz + interval '18 hours 30 minutes', 75, 'East market hall, mezzanine', 30, '00000000-0000-4000-8000-000000702633', 'Five minutes each, no slides over ten. Sign up at the door.'),
  ('00000000-0000-4000-9000-000000000003', 'Newcomers’ welcome evening', 'social', null, (current_date + ((3 - extract(dow from current_date)::int + 7) % 7) + 0)::timestamptz + interval '18 hours 0 minutes', 120, 'The cellar, Old Town brewing society', 40, '00000000-0000-4000-8000-000000702528', 'Joined this year? Come and meet a member from every chapter. First round is on the club.'),
  ('00000000-0000-4000-9000-000000000004', 'Coastal walk and talk', 'social', 'Northwest coastal chapter', (current_date + ((6 - extract(dow from current_date)::int + 7) % 7) + 0)::timestamptz + interval '10 hours 0 minutes', 150, 'Meet at the coastguard station car park', 20, '00000000-0000-4000-8000-000000702564', 'Six kilometres along the cliff path, with a stop at the lookout. Boots, not trainers.'),
  ('00000000-0000-4000-9000-000000000005', 'Portfolio review night', 'workshop', null, (current_date + ((5 - extract(dow from current_date)::int + 7) % 7) + 0)::timestamptz + interval '18 hours 0 minutes', 120, 'East market hall, mezzanine', 16, '00000000-0000-4000-8000-000000702665', 'Bring one piece of work and get three honest opinions on it. Sixteen seats, and it always fills.'),
  ('00000000-0000-4000-9000-000000000006', 'Chapter meetup', 'meetup', 'North chapter', (current_date + ((2 - extract(dow from current_date)::int + 7) % 7) + 0)::timestamptz + interval '19 hours 0 minutes', 90, 'Upper room, North Street library', 30, '00000000-0000-4000-8000-000000702598', 'The usual: news from the board, then the floor is open.'),
  ('00000000-0000-4000-9000-000000000007', 'Board games night', 'social', 'Harbour chapter', (current_date + ((1 - extract(dow from current_date)::int + 7) % 7) + 7)::timestamptz + interval '18 hours 0 minutes', 180, 'Harbour light cooperative, net loft', 24, '00000000-0000-4000-8000-000000702584', 'Bring a game you can teach in ten minutes. Tea, biscuits and fierce rivalries.'),
  ('00000000-0000-4000-9000-000000000008', 'Mentoring circle', 'workshop', 'Northwest coastal chapter', (current_date + ((4 - extract(dow from current_date)::int + 7) % 7) + 7)::timestamptz + interval '19 hours 0 minutes', 90, 'Online — link sent the day before', 12, '00000000-0000-4000-8000-000000702575', 'Three mentors, nine questions. Bring the one you have been putting off asking.'),
  ('00000000-0000-4000-9000-000000000009', 'Saturday garden morning', 'social', 'South chapter', (current_date + ((6 - extract(dow from current_date)::int + 7) % 7) + 7)::timestamptz + interval '10 hours 0 minutes', 180, 'South community garden, greenhouse', 25, '00000000-0000-4000-8000-000000702630', 'Beds to clear and a compost heap to turn. Gloves provided; lunch from the greenhouse kitchen.'),
  ('00000000-0000-4000-9000-000000000010', 'Reading group: the club’s first ten years', 'talk', 'University chapter', (current_date + ((2 - extract(dow from current_date)::int + 7) % 7) + 7)::timestamptz + interval '17 hours 30 minutes', 90, 'Seminar room 4, the old library', 20, '00000000-0000-4000-8000-000000702516', 'Two founders read from the old minutes book, and take questions after.'),
  ('00000000-0000-4000-9000-000000000011', 'Chapter meetup', 'meetup', 'West chapter', (current_date + ((5 - extract(dow from current_date)::int + 7) % 7) + 7)::timestamptz + interval '18 hours 0 minutes', 90, 'West park pavilion', 20, '00000000-0000-4000-8000-000000702667', 'Small table, long agenda: the next calendar and who is running what.'),
  ('00000000-0000-4000-9000-000000000012', 'Intro to public speaking', 'workshop', 'Old town chapter', (current_date + ((4 - extract(dow from current_date)::int + 7) % 7) + 14)::timestamptz + interval '19 hours 30 minutes', 120, 'The cellar, Old Town brewing society', 14, '00000000-0000-4000-8000-000000702708', 'A safe room to stand up and talk for two minutes. Everyone goes once; nobody is graded.'),
  ('00000000-0000-4000-9000-000000000013', 'Harbour lights photo walk', 'social', 'Harbour chapter', (current_date + ((0 - extract(dow from current_date)::int + 7) % 7) + 14)::timestamptz + interval '16 hours 0 minutes', 120, 'Meet under the harbour clock', 18, '00000000-0000-4000-8000-000000702727', 'Blue hour on the quay. Phones are cameras too.'),
  ('00000000-0000-4000-9000-000000000014', 'Inter-chapter quiz', 'social', null, (current_date + ((5 - extract(dow from current_date)::int + 7) % 7) + 14)::timestamptz + interval '18 hours 30 minutes', 150, 'Main hall, North Street library', 64, '00000000-0000-4000-8000-000000702633', 'Eight chapters, eight tables, one trophy. Points count towards the Chapter Cup.'),
  ('00000000-0000-4000-9000-000000000015', 'Chapter meetup', 'meetup', 'East chapter', (current_date + ((3 - extract(dow from current_date)::int + 7) % 7) + 14)::timestamptz + interval '18 hours 30 minutes', 90, 'East market hall, mezzanine', 30, '00000000-0000-4000-8000-000000702633', 'Planning the next round of workshops. Ideas welcome; volunteers more so.'),
  ('00000000-0000-4000-9000-000000000016', 'Budgeting for a chapter', 'workshop', null, (current_date + ((2 - extract(dow from current_date)::int + 7) % 7) + 21)::timestamptz + interval '18 hours 0 minutes', 90, 'Online — link sent the day before', 30, '00000000-0000-4000-8000-000000702710', 'For chapter leads and anyone who wants to be one: how the club splits its budget, and how to ask for more.'),
  ('00000000-0000-4000-9000-000000000017', 'Chapter meetup', 'meetup', 'Northwest coastal chapter', (current_date + ((4 - extract(dow from current_date)::int + 7) % 7) + 21)::timestamptz + interval '19 hours 0 minutes', 90, 'Coastguard station, lookout room', 25, '00000000-0000-4000-8000-000000702507', 'The in-person one. Car shares organised on the chapter thread.'),
  ('00000000-0000-4000-9000-000000000018', 'Garden lights social', 'social', 'South chapter', (current_date + ((6 - extract(dow from current_date)::int + 7) % 7) + 21)::timestamptz + interval '17 hours 0 minutes', 180, 'South community garden, greenhouse', 35, '00000000-0000-4000-8000-000000702630', 'Something warm to drink, a playlist the chapter voted on, and the greenhouse strung with lights.'),
  ('00000000-0000-4000-9000-000000000019', 'How the Chapter Cup is scored', 'talk', null, (current_date + ((3 - extract(dow from current_date)::int + 7) % 7) + 28)::timestamptz + interval '18 hours 30 minutes', 60, 'Online — link sent the day before', 50, '00000000-0000-4000-8000-000000702598', 'Season points, explained by the people who argue about them. Twenty minutes of questions.'),
  ('00000000-0000-4000-9000-000000000020', 'Reading list meetup', 'meetup', 'University chapter', (current_date + ((2 - extract(dow from current_date)::int + 7) % 7) + 28)::timestamptz + interval '17 hours 30 minutes', 120, 'Seminar room 4, the old library', 20, '00000000-0000-4000-8000-000000702641', 'Everyone brings one book for the next term’s list, and the chapter votes. Cake provided.');
